  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Determines whether a customer can book seats on a trip. The trip must exist, the trip must still have enough available seats, the requested seats must not exceed the remaining seats, and the customer must not already hold another booking whose trip time overlaps on the same day. The booking time must be strictly earlier than the departure time by more than two hours, so a booking made exactly two hours before departure is rejected. When the booking is accepted, the trip seat count shall be reduced. Invalid inputs such as a null customer, null trip, or null booking date shall return false.
   * Algorithm:
   *   if customer == null or trip == null or bookingDate == null -> return false
   *   if trip.numberOfSeats < numberOfSeats -> return false
   *   if trip.getBookedSeats() + numberOfSeats > trip.numberOfSeats -> return false
   *   for each existingBooking in customer.bookings:
   *       if existingBooking.bookingDate == bookingDate and existingBooking.overlapsWith(trip) -> return false
   *   if bookingDate is not more than 2 hours before trip.departureTime -> return false
   *   updateTripSeats()
   *   return true
   * Related Features: customer, numberOfSeats, bookingDate, trip
   * Related Classes: Customer, Trip
   * Input: none (uses instance fields: customer, numberOfSeats, bookingDate, trip)
   * Output: boolean — true if the booking is eligible and accepted, false otherwise
   * Pre-condition: The booking instance must have customer, numberOfSeats, bookingDate, and trip fields set.
   * Post-condition: If true is returned, trip numberOfSeats is reduced by numberOfSeats; otherwise no change.
   * <!-- end-model-doc -->
   * @model kind="operation"
   *        annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isBookingEligible()
  {
    if (getCustomer() == null || getTrip() == null || getBookingDate() == null)
      return false;
    
    Trip theTrip = getTrip();
    if (theTrip.getNumberOfSeats() < getNumberOfSeats())
      return false;
    
    if (theTrip.getBookedSeats() + getNumberOfSeats() > theTrip.getNumberOfSeats())
      return false;
    
    for (Booking existingBooking : getCustomer().getBookings())
    {
      if (existingBooking.getBookingDate() != null && existingBooking.getBookingDate().equals(getBookingDate()) && existingBooking.overlapsWith(theTrip))
        return false;
    }
    
    // Check if bookingDate is more than 2 hours before trip.departureTime
    // Parse departureTime string (format "HH:mm") and combine with departureDate
    try
    {
      SimpleDateFormat timeFormat = new SimpleDateFormat("HH:mm");
      Date departureTimeParsed = timeFormat.parse(theTrip.getDepartureTime());
      
      Calendar departureCal = Calendar.getInstance();
      departureCal.setTime(theTrip.getDepartureDate());
      Calendar timeCal = Calendar.getInstance();
      timeCal.setTime(departureTimeParsed);
      
      departureCal.set(Calendar.HOUR_OF_DAY, timeCal.get(Calendar.HOUR_OF_DAY));
      departureCal.set(Calendar.MINUTE, timeCal.get(Calendar.MINUTE));
      departureCal.set(Calendar.SECOND, 0);
      departureCal.set(Calendar.MILLISECOND, 0);
      
      Date departureDateTime = departureCal.getTime();
      
      // Calculate the difference in milliseconds
      long diffMillis = departureDateTime.getTime() - getBookingDate().getTime();
      long twoHoursMillis = 2 * 60 * 60 * 1000L;
      
      // bookingDate must be strictly earlier than departureTime by more than 2 hours
      if (diffMillis <= twoHoursMillis)
        return false;
    }
    catch (ParseException e)
    {
      return false;
    }
    
    updateTripSeats();
    return true;
  }

